  const filtered = useMemo(() => allDestinations.filter((d) => {
    const matchesQuery = `${d.name} ${d.state} ${d.type}`.toLowerCase().includes(query.toLowerCase())
    const matchesCrowd = crowd === 'All crowd levels' || d.crowd === crowd
    const matchesStyle = travelStyle === 'Any preference' || (travelStyle === 'Nature' ? d.type === 'Nature' || d.activities.includes('Nature') : d.type === travelStyle)
    const matchesGroup = tripGroup === 'Any group' || (tripGroup === 'Family' ? d.access === 'Good access' : tripGroup === 'Solo' ? d.type !== 'Beach' : true)
    const matchesBudget = budget === 'Any budget' || (budget === 'Budget friendly' ? d.crowd !== 'High crowd' : budget === 'Premium' ? d.score >= 88 : true)
    return matchesQuery && matchesCrowd && matchesStyle && matchesGroup && matchesBudget
  }), [query, crowd, travelStyle, tripGroup, budget])

  const go = (next: typeof view) => { setView(next); setMenuOpen(false); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const runEngine = () => setRecommendations(destinations.filter((d) => d.crowd === 'Low crowd').slice(0, 3))
  const toggleSave = (id: number) => setSaved((items) => items.includes(id) ? items.filter((item) => item !== id) : [...items, id])

